pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let key = call.try_intern(b"FOV")?;
    let value = call.raw_table_get(actor, key)?;
    if value != Value::Nil {
        scalar(
            store,
            actor,
            "fov",
            super::sprites::number(call, value)? as f32,
        );
    }
    Ok(())
}

pub(super) fn text<'a>(call: &'a HostCall<'_>, value: Value) -> Option<&'a str> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?).ok()
}

fn alignment(call: &HostCall<'_>, value: Value, vertical: bool) -> Option<f32> {
    if let Some(number) = float_scalar(call, value, false) {
        return Some(number);
    }
    let token = crate::borrowed_alignment_token(text(call, value)?);
    if token.eq_ignore_ascii_case(if vertical { "top" } else { "left" }) {
        Some(0.0)
    } else if token.eq_ignore_ascii_case("center") || token.eq_ignore_ascii_case("middle") {
        Some(0.5)
    } else if token.eq_ignore_ascii_case(if vertical { "bottom" } else { "right" }) {
        Some(1.0)
    } else {
        None
    }
}

pub(super) fn color(call: &mut HostCall<'_>) -> Result<Option<[f32; 4]>, Error> {
    color_at(call, 1)
}
pub(super) fn color_at(call: &mut HostCall<'_>, offset: usize) -> Result<Option<[f32; 4]>, Error> {
    match arg(call, offset) {
        Value::Table(table) => {
            let mut out = [1.0; 4];
            for (i, component) in out.iter_mut().enumerate() {
                let value = call.raw_table_get(table, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                // The production table reader uses Lua numeric coercion, which
                // accepts hex strings and nonfinite numbers. It ignores __index.
                let converted = call.call(helper(call, 6)?, &[value])?[0];
                let Value::Number(number) = converted else {
                    return Ok(None);
                };
                *component = number as f32;
            }
            Ok(Some(out))
        }
        Value::String(_) => Ok(text(call, arg(call, offset))
            .map(|text| crate::parse_color_text(text).unwrap_or([1.0; 4]))),
        first => {
            let Some(r) = float_scalar(call, first, false) else {
                return Ok(None);
            };
            let Some(g) = float_scalar(call, arg(call, offset + 1), false) else {
                return Ok(None);
            };
            let Some(b) = float_scalar(call, arg(call, offset + 2), false) else {
                return Ok(None);
            };
            Ok(Some([
                r,
                g,
                b,
                float_scalar(call, arg(call, offset + 3), false).unwrap_or(1.0),
            ]))
        }
    }
}

fn push_color(call: &mut HostCall<'_>, color: [f32; 4]) -> Result<(), Error> {
    let table = call.try_new_table()?;
    call.with_roots(&[Value::Table(table)], |call| {
        for (i, component) in color.into_iter().enumerate() {
            call.raw_table_set(
                table,
                Value::Number((i + 1) as f64),
                Value::Number(component as f64),
            )?;
        }
        call.push(Value::Table(table))
    })
}

fn strict_boolean(call: &HostCall<'_>, name: &str) -> Result<bool, Error> {
    match arg(call, 1) {
        Value::Boolean(value) => Ok(value),
        Value::Number(value) => Ok(value.trunc() != 0.0),
        _ => Err(call.error(format!("{name} expects a boolean or number").as_bytes())),
    }
}

fn cull_mode(call: &HostCall<'_>) -> Result<CullMode, Error> {
    match arg(call, 1) {
        Value::Number(0.0) => Ok(CullMode::Back),
        Value::Number(1.0) => Ok(CullMode::Front),
        Value::Number(2.0) => Ok(CullMode::None),
        value => match text(call, value) {
            Some("CullMode_Back") => Ok(CullMode::Back),
            Some("CullMode_Front") => Ok(CullMode::Front),
            Some("CullMode_None") => Ok(CullMode::None),
            Some(value) if value.eq_ignore_ascii_case("back") => Ok(CullMode::Back),
            Some(value) if value.eq_ignore_ascii_case("front") => Ok(CullMode::Front),
            Some(value) if value.eq_ignore_ascii_case("none") => Ok(CullMode::None),
            _ => Err(call.error(b"invalid CullMode")),
        },
    }
}

fn depth(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    test: Option<(bool, bool)>,
    write: Option<bool>,
) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some((enabled, on_fail)) = test {
            render.depth_test = enabled;
            render.depth_test_on_fail = on_fail;
        }
        if let Some(enabled) = write {
            render.depth_write = enabled;
        }
    }
    for child in children(call, store, actor)? {
        depth(call, store, child, test, write)?;
    }
    Ok(())
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    if matches!(name, "FullScreen" | "Center" | "CenterX" | "CenterY") {
        screen_geometry(call, store, actor, name)?;
        return call.push(Value::Table(actor));
    }
    // Parse values before taking the metadata lock. Lua numeric conversion and
    // return-table allocation may reenter the VM or collect traced captures.
    if matches!(name, "GetDiffuse" | "GetGlow") {
        let color = {
            let store = store.lock().unwrap();
            let pose = store.actors[&actor].destination();
            if name == "GetDiffuse" {
                pose.diffuse
            } else {
                pose.glow
            }
        };
        return push_color(call, color);
    }
    if name == "getrotation" {
        let rotation = store.lock().unwrap().actors[&actor].state.rotation;
        for value in rotation {
            call.push(Value::Number(value as f64))?;
        }
        return Ok(());
    }
    if name.starts_with("Get") {
        let value = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            let render = &actor.state.render;
            match name {
                "GetDiffuseAlpha" => actor.destination().diffuse[3],
                "GetBaseZoomX" => render.basezoom_x,
                "GetBaseZoomY" => render.basezoom_y,
                "GetBaseZoomZ" => render.basezoom_z,
                "GetHAlign" => render.halign,
                "GetVAlign" => render.valign,
                _ => unreachable!(),
            }
        };
        return call.push(Value::Number(value as f64));
    }
    if matches!(name, "diffuse" | "diffusecolor" | "glow" | "shadowcolor")
        || corner_mask(name).is_some()
    {
        if let Some(mut color) = color(call)? {
            let shared = store;
            let id = actor;
            let mut store = store.lock().unwrap();
            let sync = !store.playback && matches!(name, "diffuse" | "diffusecolor");
            let actor = store.actors.get_mut(&actor).unwrap();
            if name == "shadowcolor" {
                actor.state.render.shadow_color = color;
            } else {
                let pose = actor.destination_mut();
                if let Some(mask) = corner_mask(name) {
                    for (i, vertex) in pose
                        .vertex_colors
                        .get_or_insert([[1.0; 4]; 4])
                        .iter_mut()
                        .enumerate()
                    {
                        if mask & (1 << i) != 0 {
                            *vertex = color;
                        }
                    }
                } else if name == "glow" {
                    pose.glow = color;
                } else {
                    if name == "diffusecolor" {
                        color[3] = pose.diffuse[3];
                    }
                    pose.diffuse = color;
                }
            }
            if sync {
                actor.sync_rotation_getters();
            }
            drop(store);
            capture::property(
                shared,
                id,
                if corner_mask(name).is_some() {
                    "vertex_colors"
                } else {
                    name
                },
            );
        }
    } else if matches!(name, "halign" | "valign" | "horizalign" | "vertalign") {
        let align = alignment(call, value, matches!(name, "valign" | "vertalign"));
        let text_align = (name == "horizalign")
            .then(|| text(call, value).and_then(crate::parse_overlay_text_align))
            .flatten();
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some(value) = align {
            if matches!(name, "valign" | "vertalign") {
                render.valign = value;
            } else {
                render.halign = value;
            }
        }
        if let Some(value) = text_align {
            render.text_align = value;
        }
    } else if name == "backfacecull" || name == "cullmode" {
        let mode = if name == "backfacecull" {
            if strict_boolean(call, name)? {
                CullMode::Back
            } else {
                CullMode::None
            }
        } else {
            cull_mode(call)?
        };
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .cull_mode = mode;
    } else if matches!(name, "zbuffer" | "ztest" | "zwrite") {
        let enabled = strict_boolean(call, name)?;
        depth(
            call,
            store,
            actor,
            (name != "zwrite").then_some((enabled, false)),
            (name != "ztest").then_some(enabled),
        )?;
    } else if name == "ztestmode" {
        let mode = text(call, value).ok_or_else(|| call.error(b"ztestmode expects a ZTestMode"))?;
        let flags = match mode
            .trim()
            .trim_start_matches("ZTestMode_")
            .to_ascii_lowercase()
            .as_str()
        {
            "off" => (false, false),
            "writeonpass" => (true, false),
            "writeonfail" => (true, true),
            _ => return Err(call.error(format!("invalid ZTestMode: {mode}").as_bytes())),
        };
        depth(call, store, actor, Some(flags), None)?;
    } else if matches!(name, "SetTextureFiltering" | "SetDrawByZPosition") {
        let enabled = call
            .arguments()
            .get(1)
            .is_none_or(|v| !matches!(v, Value::Nil | Value::Boolean(false)));
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if name == "SetTextureFiltering" {
            render.texture_filtering = enabled;
        } else {
            render.draw_by_z_position = enabled;
        }
    } else if name == "blend" {
        if let Some(blend) = text(call, value).and_then(crate::parse_overlay_blend_mode) {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .blend = blend;
        }
    } else if matches!(
        name,
        "stretchto"
            | "scaletofit"
            | "scaletocover"
            | "zoomto"
            | "zoomtowidth"
            | "zoomtoheight"
            | "vanishpoint"
    ) {
        geometry(call, store, actor, name)?;
    } else if name != "clearzbuffer" {
        let nonfinite = matches!(
            name,
            "croptop"
                | "cropbottom"
                | "fadeleft"
                | "faderight"
                | "fadetop"
                | "fadebottom"
                | "basealpha"
                | "heading"
                | "pitch"
                | "roll"
        ) || (name == "diffusealpha"
            && matches!(value, Value::Number(v) if v.is_infinite()));
        if let Some(number) = float_scalar(call, value, nonfinite) {
            scalar(store, actor, name, number);
        }
    }
    call.push(Value::Table(actor))
}

fn corner_mask(name: &str) -> Option<u8> {
    Some(match name {
        "diffuseupperleft" => 1,
        "diffuseupperright" => 2,
        "diffuselowerleft" => 4,
        "diffuselowerright" => 8,
        "diffuseleftedge" => 5,
        "diffuserightedge" => 10,
        "diffusetopedge" => 3,
        "diffusebottomedge" => 12,
        _ => return None,
    })
}

fn scalar(store: &Shared, actor: TableId, name: &str, value: f32) {
    let shared = store;
    let id = actor;
    let mut store = store.lock().unwrap();
    let sync = name == "diffusealpha" && !store.playback;
    let actor = store.actors.get_mut(&actor).unwrap();
    let render = &mut actor.state.render;
    match name {
        "basealpha" => render.base_alpha = value,
        "basezoom" => {
            render.basezoom = value;
            render.basezoom_x = value;
            render.basezoom_y = value;
            render.basezoom_z = value;
        }
        "basezoomx" => render.basezoom_x = value,
        "basezoomy" => render.basezoom_y = value,
        "basezoomz" => render.basezoom_z = value,
        "baserotationx" => render.base_rotation[0] = value,
        "baserotationy" => render.base_rotation[1] = value,
        "baserotationz" => render.base_rotation[2] = value,
        "shadowlength" => render.shadow_len = [value, -value],
        "shadowlengthx" => render.shadow_len[0] = value,
        "shadowlengthy" => render.shadow_len[1] = -value,
        "zbias" => render.z_bias = value,
        "fov" => render.fov = (value != -1.0).then_some(value),
        _ => {
            let pose = actor.destination_mut();
            match name {
                "cropleft" => pose.cropleft = value,
                "cropright" => pose.cropright = value,
                "croptop" => pose.croptop = value,
                "cropbottom" => pose.cropbottom = value,
                "fadeleft" => pose.fadeleft = value,
                "faderight" => pose.faderight = value,
                "fadetop" => pose.fadetop = value,
                "fadebottom" => pose.fadebottom = value,
                "skewx" => pose.skew_x = value,
                "skewy" => pose.skew_y = value,
                "diffusealpha" => pose.diffuse[3] = value,
                "heading" | "pitch" | "roll" => {
                    let axis = match name {
                        "heading" => 1,
                        "pitch" => 0,
                        _ => 2,
                    };
                    pose.quaternion = crate::actor_quaternion::rotate(pose.quaternion, axis, value);
                }
                _ => unreachable!(),
            }
        }
    }
    if sync {
        actor.sync_rotation_getters();
    }
    drop(store);
    capture::property(shared, id, name);
}

fn geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let count = match name {
        "zoomtowidth" | "zoomtoheight" => 1,
        "zoomto" | "vanishpoint" => 2,
        _ => 4,
    };
    let mut values = [0.0; 4];
    for (i, value) in values.iter_mut().enumerate().take(count) {
        match float_scalar(call, arg(call, i + 1), false) {
            Some(number) => *value = number,
            None if name == "stretchto" => {}
            None => return Ok(()),
        }
    }
    geometry_values(call, store, actor, name, values)
}

fn screen_size(call: &mut HostCall<'_>) -> Result<[f32; 2], Error> {
    let globals = super::table(call, helper(call, 5)?)?;
    let mut size = [640., 480.];
    for (index, key) in ["SCREEN_WIDTH", "SCREEN_HEIGHT"].into_iter().enumerate() {
        let value = super::sprites::field(call, globals, key)?;
        if value != Value::Nil {
            let number = super::sprites::number(call, value)?.trunc();
            if !(i32::MIN as f64..=i32::MAX as f64).contains(&number) {
                return Err(call.error(b"screen size out of range"));
            }
            size[index] = number as i32 as f32;
        }
    }
    Ok(size)
}

fn screen_geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if name == "FullScreen" {
        let [width, height] = screen_size(call)?;
        return geometry_values(call, store, actor, "stretchto", [0., 0., width, height]);
    }
    let globals = super::table(call, helper(call, 5)?)?;
    let mut center = [0.; 2];
    for (index, key) in ["SCREEN_CENTER_X", "SCREEN_CENTER_Y"]
        .into_iter()
        .enumerate()
    {
        let value = super::sprites::field(call, globals, key)?;
        let value = if value == Value::Nil {
            None
        } else {
            Some(super::sprites::number(call, value)? as f32)
        };
        // The original helper eagerly evaluates its size fallback, even with
        // an explicit center; invalid dimensions must still report an error.
        center[index] = value.unwrap_or(screen_size(call)?[index] * 0.5);
    }
    let mut guard = store.lock().unwrap();
    let pose = guard.actors.get_mut(&actor).unwrap().destination_mut();
    if name != "CenterY" {
        pose.x = center[0];
    }
    if name != "CenterX" {
        pose.y = center[1];
    }
    drop(guard);
    capture::property(store, actor, name);
    Ok(())
}

fn geometry_values(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
    values: [f32; 4],
) -> Result<(), Error> {
    if name != "vanishpoint" {
        super::sprites::refresh_size(call, store, actor)?;
    }
    let bitmap = store.lock().unwrap().actors[&actor].state.class == "BitmapText";
    let text_height =
        bitmap && name == "zoomtoheight" && !super::text::content(call, actor)?.is_empty();
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    if bitmap && (matches!(name, "zoomto" | "zoomtowidth") || text_height) {
        let [width, height] = actor.state.size.map(f32::abs);
        let size = match name {
            "zoomtowidth" => [values[0], height],
            "zoomtoheight" => [width, values[0]],
            _ => [values[0], values[1]],
        };
        actor.state.size = size;
        actor.state.render.size = Some(size);
        drop(guard);
        capture::property(store, id, "size");
        return Ok(());
    }
    let mut scaled = false;
    let [width, height] = actor.state.size.map(f32::abs);
    let render = &mut actor.state.render;
    if name == "vanishpoint" {
        render.vanishpoint = Some([values[0], values[1]]);
        return Ok(());
    }
    let align = [render.halign, render.valign];
    let pose = actor.destination_mut();
    match name {
        "zoomtowidth" => pose.zoom_x = values[0] / width,
        "zoomtoheight" => pose.zoom_y = values[0] / height,
        "zoomto" => {
            pose.zoom_x = values[0] / width;
            pose.zoom_y = values[1] / height;
        }
        "stretchto" => {
            let w = values[2] - values[0];
            let h = values[3] - values[1];
            pose.x = values[0] + w / 2.0;
            pose.y = values[1] + h / 2.0;
            pose.zoom_x = w / width;
            pose.zoom_y = h / height;
        }
        "scaletofit" | "scaletocover" => {
            if let Some(plan) =
                crate::scale_to_rect_plan(values, [width, height], align, name == "scaletocover")
            {
                scaled = true;
                pose.x = plan.pos[0];
                pose.y = plan.pos[1];
                pose.zoom = plan.zoom;
                pose.zoom_x = plan.zoom;
                pose.zoom_y = plan.zoom;
                pose.zoom_z = plan.zoom;
                if plan.flip_x {
                    pose.rot_y_deg = 180.0;
                }
                if plan.flip_y {
                    pose.rot_x_deg = 180.0;
                }
                if plan.flip_x {
                    actor.state.rotation[1] = 180.0;
                }
                if plan.flip_y {
                    actor.state.rotation[0] = 180.0;
                }
            }
        }
        _ => unreachable!(),
    }
    drop(guard);
    capture::property(store, id, name);
    if scaled {
        super::text::pre_zoom(call, store, id, true, true)?;
    }
    Ok(())
}

//! Original gameplay underlay files and their native load/Init/message order.
use super::*;

const ENVIRONMENT: &[u8] = b"__songlua_step_statistics_environment";

fn invoke(
    call: &mut HostCall<'_>,
    owner: TableId,
    name: &str,
    args: &[Value],
) -> Result<Value, Error> {
    call.with_roots(&[Value::Table(owner)], |call| {
        let function = field(call, owner, name)?;
        let mut values = Vec::with_capacity(args.len() + 1);
        values.push(Value::Table(owner));
        values.extend_from_slice(args);
        Ok(call
            .call(function, &values)?
            .first()
            .copied()
            .unwrap_or(Value::Nil))
    })
}

fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

fn named(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<TableId, Error> {
    let children = registry(call, actor)?;
    call.with_roots(&[children], |call| {
        let value = get(call, table(call, children)?, name.as_bytes())?;
        table(call, value)
    })
}

fn environment(call: &mut HostCall<'_>) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let existing = get(call, globals, ENVIRONMENT)?;
    if existing != Value::Nil {
        table(call, existing)?;
        return Ok(existing);
    }
    let environment = source::environment(call, Value::Table(globals), true)?;
    call.with_roots(&[environment], |call| {
        let key = call.try_intern(ENVIRONMENT)?;
        call.raw_table_set(globals, key, environment)?;
        let captures = call.captures().to_vec();
        let loader = call.new_host_function(step_resource, &captures)?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(call, source::HISTOGRAM, environment, &[])?;
        Ok(environment)
    })
}

fn step_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let path = assets::text(call, arg(call, 0))?;
    let globals = table(call, helper(call, 5)?)?;
    let environment = get(call, globals, ENVIRONMENT)?;
    table(call, environment)?;
    let args = call.arguments().iter().skip(1).copied().collect::<Vec<_>>();
    let value = step(call, environment, &path, &args)?;
    call.push(value)
}

fn step(
    call: &mut HostCall<'_>,
    environment: Value,
    path: &str,
    args: &[Value],
) -> Result<Value, Error> {
    let name = path.strip_prefix("./").unwrap_or(path);
    let source = source::statistics(name).ok_or_else(|| {
        call.error(format!("unknown native StepStatistics resource {path}").as_bytes())
    })?;
    source::evaluate(call, source, environment, args)
}

fn note_field(call: &mut HostCall<'_>, path: &str, args: &[Value]) -> Result<Value, Error> {
    let source = source::note_field(path)
        .ok_or_else(|| call.error(format!("unknown native NoteField actor {path}").as_bytes()))?;
    let globals = helper(call, 5)?;
    let environment = source::environment(call, globals, true)?;
    call.with_roots(&[environment], |call| {
        let directory = path
            .rsplit_once('/')
            .map_or_else(String::new, |(parent, _)| format!("{parent}/"));
        let captures = call.captures().to_vec();
        let loader = call.new_host_function_with_data(note_resource, &captures, directory)?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(call, source, environment, args)
    })
}

fn note_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let directory = call.function_data::<String>().unwrap().clone();
    let child = assets::text(call, arg(call, 0))?;
    let args = call.arguments().iter().skip(1).copied().collect::<Vec<_>>();
    let path = format!("{directory}{}", child.trim_start_matches("./"));
    let value = note_field(call, &path, &args)?;
    call.push(value)
}

fn player(call: &HostCall<'_>, value: Value) -> Option<usize> {
    match value {
        Value::Number(value)
            if value >= 0. && value < crate::LUA_PLAYERS as f64 && value.fract() == 0. =>
        {
            Some(value as usize)
        }
        Value::String(id) => {
            let bytes = call.string_bytes(id)?;
            [b"P1".as_slice(), b"P2"]
                .iter()
                .position(|name| bytes.eq_ignore_ascii_case(name))
                .or_else(|| {
                    [b"PlayerNumber_P1".as_slice(), b"PlayerNumber_P2"]
                        .iter()
                        .position(|name| bytes.eq_ignore_ascii_case(name))
                })
        }
        _ => None,
    }
}

fn attach(
    call: &mut HostCall<'_>,
    data: &Load,
    underlay: TableId,
    definition: Value,
    lookup: bool,
    name: Option<&str>,
) -> Result<TableId, Error> {
    let actor = own(call, data, definition)?;
    parent(call, &data.store, actor, underlay)?;
    initialize(call, &data.store, actor)?;
    if lookup {
        owned_lookup(call, actor)?;
    }
    let name = match name {
        Some(name) => name.as_bytes().to_vec(),
        None => actor_name(call, &data.store, actor)?,
    };
    let children = registry(call, underlay)?;
    call.with_roots(&[children], |call| {
        let key = call.try_intern(&name)?;
        call.raw_table_set(table(call, children)?, key, Value::Table(actor))
    })?;
    let count = call.raw_table_len(underlay)?;
    let mut found = false;
    for index in 1..=count {
        found |= call.raw_table_get(underlay, Value::Number(index as f64))? == Value::Table(actor);
    }
    if !found {
        call.raw_table_set(
            underlay,
            Value::Number((count + 1) as f64),
            Value::Table(actor),
        )?;
        data.store
            .lock()
            .unwrap()
            .actors
            .get_mut(&underlay)
            .unwrap()
            .children
            .push(actor);
    }
    Ok(actor)
}

// These theme phases call the raw Begin/On handlers directly, without the
// authored playcommand wrapper. Enumerate children after each parent callback.
fn command(call: &mut HostCall<'_>, actor: TableId, name: &[u8]) -> Result<(), Error> {
    let callback = get(call, actor, name)?;
    if callback != Value::Nil {
        if !matches!(callback, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"theme actor command must be a function"));
        }
        call.call(callback, &[Value::Table(actor)])?;
    }
    native_children::with_children(call, actor, |call, child| command(call, child, name))
}

pub(super) fn load(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let environment = environment(call)?;
    call.with_roots(&[environment], |call| {
        let globals = table(call, helper(call, 5)?)?;
        let screen = get(call, globals, b"__songlua_top_screen")?;
        let screen = table(call, screen)?;
        let underlay = named(call, screen, "Underlay")?;
        let game = member(call, globals, "GAMESTATE")?;
        let players = invoke(call, game, "GetHumanPlayers", &[])?;
        table(call, players)?;
        call.with_roots(&[players], |call| {
            data.store
                .lock()
                .unwrap()
                .startup_queues
                .get_or_insert_with(Vec::new);
            source::evaluate(call, source::UTF8, Value::Table(globals), &[])?;
            source::evaluate(call, source::TEXT_HELPERS, Value::Table(globals), &[])?;
            steps_displays::initialize(call, &data.store, screen)?;
            for index in 1.. {
                let value =
                    call.raw_table_get(table(call, players)?, Value::Number(index as f64))?;
                if value == Value::Nil {
                    break;
                }
                let Some(player) = player(call, value) else {
                    continue;
                };
                let child = named(call, screen, &format!("PlayerOptionsP{}", player + 1))?;
                let game = member(call, globals, "GAMESTATE")?;
                let state = invoke(call, game, "GetPlayerState", &[value])?;
                call.with_roots(&[state], |call| {
                    let level = call.try_intern(b"ModsLevel_Current")?;
                    let text = invoke(
                        call,
                        table(call, state)?,
                        "GetPlayerOptionsString",
                        &[level],
                    )?;
                    let text = assets::text(call, text)?;
                    let text = call.try_intern(text.as_bytes())?;
                    set(call, child, "Text", text)
                })?;
            }
            let mut panes = Vec::new();
            for index in 1.. {
                let player =
                    call.raw_table_get(table(call, players)?, Value::Number(index as f64))?;
                if player == Value::Nil {
                    break;
                }
                let danger =
                    source::evaluate(call, source::DANGER, Value::Table(globals), &[player])?;
                if danger != Value::Nil {
                    panes.push(attach(call, data, underlay, danger, false, None)?);
                }
                let pane = step(call, environment, "default.lua", &[player])?;
                if pane != Value::Nil {
                    panes.push(attach(call, data, underlay, pane, true, None)?);
                }
                let container = note_field(call, "default.lua", &[player])?;
                panes.push(attach(call, data, underlay, container, true, None)?);
            }
            let meter = source::evaluate(call, source::SONG_INFO, Value::Table(globals), &[])?;
            panes.push(attach(
                call,
                data,
                underlay,
                meter,
                true,
                Some("SongMeter"),
            )?);
            reorder(call, data, underlay)?;
            set(
                call,
                underlay,
                "__songlua_owned_child_lookup",
                Value::Boolean(true),
            )?;
            for &pane in &panes {
                command(call, pane, b"BeginCommand")?;
            }
            for &pane in &panes {
                command(call, pane, b"OnCommand")?;
            }
            // Keep normal listener delivery; this internal song-change event
            // does not record an authored Broadcast or increment its counter.
            messages::dispatch(call, &data.store, b"CurrentSongChanged", None, false)
        })
    })
}

fn reorder(call: &mut HostCall<'_>, data: &Load, underlay: TableId) -> Result<(), Error> {
    const ORDER: &[&[u8]] = &[
        b"DangerP1",
        b"StepStatsPaneP1",
        b"filter0",
        b"DangerP2",
        b"StepStatsPaneP2",
        b"filter1",
        b"Header",
        b"SongMeter",
        b"P1Score",
        b"difficulty0",
        b"life0",
        b"NoteFieldContainerP1",
        b"P2Score",
        b"difficulty1",
        b"life1",
        b"NoteFieldContainerP2",
        b"bpm",
    ];
    let mut children = Vec::new();
    native_children::with_children(call, underlay, |call, child| {
        let name = actor_name(call, &data.store, child).unwrap_or_default();
        let role = get(call, child, b"__songlua_underlay_role")
            .ok()
            .and_then(|value| {
                if value == Value::Nil {
                    None
                } else {
                    assets::text(call, value).ok()
                }
            });
        let name = role
            .as_ref()
            .map_or(name.as_slice(), |role| role.as_bytes());
        let rank = ORDER.iter().position(|&role| name == role).unwrap_or(99);
        children.push((rank, child));
        Ok(())
    })?;
    children.sort_by_key(|&(rank, _)| rank);
    for (index, &(_, child)) in children.iter().enumerate() {
        call.raw_table_set(
            underlay,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    data.store
        .lock()
        .unwrap()
        .actors
        .get_mut(&underlay)
        .unwrap()
        .children = children.into_iter().map(|(_, child)| child).collect();
    Ok(())
}

